trivy fs --severity HIGH,CRITICAL,MEDIUM,LOW --format json package-lock.json 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
targets = ['form-data','braces','cross-spawn','json5','marked','qs','ws','@babel/traverse','@xmldom/xmldom','tar-fs']
for r in data.get('Results',[]):
    for v in r.get('Vulnerabilities',[]):
        pkg = v.get('PkgName','')
        if pkg in targets:
            cvss = v.get('CVSS',{})
            scores = {}
            for k,val in cvss.items():
                if isinstance(val, dict) and 'V3Score' in val:
                    scores[k] = val['V3Score']
            print(json.dumps({
                'pkg':pkg,
                'id':v.get('VulnerabilityID',''),
                'severity':v.get('Severity',''),
                'installed':v.get('InstalledVersion',''),
                'fixed':v.get('FixedVersion',''),
                'title':v.get('Title',''),
                'scores':scores,
                'url':v.get('PrimaryURL','')
            }))
" 2>&1

