import json

with open('/tmp/trivy_all.json') as f:
    data = json.load(f)

targets = ['form-data','braces','cross-spawn','json5','marked','qs','ws','@babel/traverse','@xmldom/xmldom','tar-fs']
for r in data.get('Results',[]):
    for v in r.get('Vulnerabilities',[]):
        pkg = v.get('PkgName','')
        if pkg in targets:
            cvss = v.get('CVSS',{})
            scores = {}
            for k,val in cvss.items():
                if isinstance(val, dict) and 'V3Score' in val:
                    scores[k] = val['V3Score']
            print(json.dumps({
                'pkg':pkg,
                'id':v.get('VulnerabilityID',''),
                'severity':v.get('Severity',''),
                'installed':v.get('InstalledVersion',''),
                'fixed':v.get('FixedVersion',''),
                'title':v.get('Title',''),
                'scores':scores,
                'url':v.get('PrimaryURL','')
            }))
PYEOF

python3 << 'PYEOF'
import json

with open('/tmp/trivy_output.json') as f:
    data = json.load(f)

for r in data.get('Results', []):
    for v in r.get('Vulnerabilities', []):
        if v.get('Severity','').upper() in ('HIGH','CRITICAL'):
            cvss = v.get('CVSS', {})
            all_scores = {}
            for source, details in cvss.items():
                if isinstance(details, dict):
                    score = details.get('V3Score')
                    if score:
                        all_scores[source] = score
            print(f"{v['PkgName']} | {v['VulnerabilityID']} | scores={all_scores}")
PYEOF

